"""Keep the loader companion separate from the firmware's real C API."""
from pathlib import Path
import sys

sharp = Path(sys.argv[1])
catalog = sharp / 'tools/SharpProspero.Prx/StubCatalog.cs'
s = catalog.read_text(encoding='utf-8')
s = s.replace('new Entry("libc", C),',
    'new Entry("libc", new[] { "Need_sceLibc" }),\n'
    '        new Entry("libSceLibcInternal", System.Linq.Enumerable.ToArray(\n'
    '            System.Linq.Enumerable.Where(C, name => name != "Need_sceLibc"))),')
catalog.write_text(s, encoding='utf-8')
# libunwind's public SDK build expects conventional section-boundary symbols.
linker = sharp / 'tools/SharpProspero.Link/Linker.cs'
s = linker.read_text(encoding='utf-8')
s = s.replace('CompatEmitter.FrameIndexEndSymbol,',
    'CompatEmitter.FrameIndexEndSymbol, "__eh_frame_start", "__eh_frame_end",\n'
    '            "__eh_frame_hdr_start", "__eh_frame_hdr_end",') if '"__eh_frame_start"' not in s else s
linker.write_text(s, encoding='utf-8')
writer = sharp / 'tools/SharpProspero.Link/DynamicWriter.cs'
s = writer.read_text(encoding='utf-8')
data_anchor = 'var dataImports = new HashSet<string>(StringComparer.Ordinal);'
if 'Public PS5 headers declare these as variables' not in s:
    s = s.replace(data_anchor, data_anchor + '''
        // Public PS5 headers declare these as variables, but the native compiler
        // leaves their undefined ELF symbols as NOTYPE. FUNC imports can bind to
        // execute-only call stubs, so dereferencing them faults before main.
        dataImports.UnionWith(new[] { "_CurrentRuneLocale", "_DefaultRuneLocale",
            "__isthreaded", "__mb_cur_max", "__mb_sb_limit" });
''')
loop = 'foreach (ElfRelocation r in kv.Value)\n                {\n'
if 'if (r.Type == RelType.None) continue;' not in s:
    s = s.replace(loop, loop + '                    if (r.Type == RelType.None) continue;\n')
anchor = 'linkerDefined[CompatEmitter.TextEndSymbol] = textSegEndAddr;'
section_anchor = 'ulong SectionAddr(ElfObject o, int i)\n        {\n'
if 'a discarded COMDAT section has no retained counterpart' not in s:
    s = s.replace(section_anchor, section_anchor + '''            if (resolution.DroppedSections.Contains((o, i)))
            {
                foreach (ElfSectionGroup group in o.Groups)
                    if (group.Members.Contains(i))
                        foreach (ElfObject retained in resolution.Included)
                            foreach (ElfSectionGroup candidate in retained.Groups)
                                if (candidate.Signature == group.Signature)
                                    foreach (int member in candidate.Members)
                                        if (!resolution.DroppedSections.Contains((retained, member))
                                            && retained.Sections[member].Name == o.Sections[i].Name)
                                            return SectionAddr(retained, member);
                throw new ElfLinkException($"{o.Origin}: a discarded COMDAT section has no retained counterpart: {o.Sections[i].Name}.");
            }
''')
comdat_anchor = 'if (resolution.DroppedSections.Contains((o, i)))\n            {\n'
if 'A partial link may merge the retained function into a larger section.' not in s:
    s = s.replace(comdat_anchor, comdat_anchor + '''                // A partial link may merge the retained function into a larger section.
                foreach (ElfSymbol original in o.Symbols)
                    if (original.SectionIndex == i && original.IsGlobalOrWeak
                        && resolution.Defined.TryGetValue(original.Name, out ElfObject? owner))
                        foreach (ElfSymbol kept in owner.Symbols)
                            if (kept.Name == original.Name && !kept.IsUndefined
                                && !resolution.DroppedSections.Contains((owner, kept.SectionIndex)))
                                return SectionAddr(owner, kept.SectionIndex) + kept.Value - original.Value;
''')
if 'linkerDefined["__eh_frame_start"]' not in s:
    s = s.replace(anchor, anchor + '\n'
        '        linkerDefined["__eh_frame_hdr_start"] = ehFrameHdrAddr;\n'
        '        linkerDefined["__eh_frame_hdr_end"] = ehFrameHdrAddr + (ulong)ehFrameHdrSize;\n'
        '        linkerDefined["__eh_frame_start"] = ehFrames.Count > 0 ? roAddr + ehFrames.Min(f => sectionOffsetInGroup[f]) : roAddr;\n'
        '        linkerDefined["__eh_frame_end"] = ehFrames.Count > 0 ? roAddr + ehFrames.Max(f => sectionOffsetInGroup[f] + f.Obj.Sections[f.Index].Size) : roAddr;')
writer.write_text(s, encoding='utf-8')

# Preserve all relocation tables targeting a merged section (RADV partial link).
reader = sharp / "tools/SharpProspero.Link/ElfObjectReader.cs"
s = reader.read_text(encoding='utf-8')
s = s.replace('            result[(int)raw[i].Info] = list; // sh_info is the target section index', '            // Partial links can retain several relocation tables for one target section.\n            // Preserve every table instead of replacing earlier records.\n            int target = (int)raw[i].Info;\n            if (result.TryGetValue(target, out IReadOnlyList<ElfRelocation>? previous))\n                list.InsertRange(0, previous);\n            result[target] = list;')
reader.write_text(s, encoding='utf-8')

# Enable native chdir: the PS5 exports it and startup uses /app0 as cwd.
compat = sharp / 'tools/SharpProspero.Link/CompatEmitter.cs'
s = compat.read_text(encoding='utf-8').replace('Refuse("chdir"),', 'Forward("chdir", "__sp_device_chdir"),')
compat.write_text(s, encoding='utf-8')
# Bind imported function GOT calls through PLT slots, preserving data imports.
writer = sharp / "tools/SharpProspero.Link/DynamicWriter.cs"
s = writer.read_text(encoding='utf-8')
if "Imported functions reached through GOT calls" not in s:
    s = s.replace('        var dynsym = new List<byte>(new byte[24]);', '        // Imported functions reached through GOT calls need real PLT binding slots.\n        // Their separate GOT addresses point to the module-local PLT thunks.\n        foreach (string name in gotDataOrder)\n            if (importByName.ContainsKey(name) && !dataImports.Contains(name))\n                calledImports.Add(name);\n\n        var dynsym = new List<byte>(new byte[24]);')
s = s.replace('            if (importByName.TryGetValue(gotDataOrder[i], out Import? imp))\n                dynRelocs.Add(new DynReloc(slot, RGlobDat, (uint)imp.DynSymIndex, 0));', '            if (importByName.TryGetValue(gotDataOrder[i], out Import? imp))\n            {\n                if (dataImports.Contains(imp.PlainName))\n                    dynRelocs.Add(new DynReloc(slot, RGlobDat, (uint)imp.DynSymIndex, 0));\n                else\n                    dynRelocs.Add(new DynReloc(slot, RRelative, 0, imp.PltAddress));\n            }')
writer.write_text(s, encoding='utf-8')

# Commit mixed reserved/backed ranges one PS5 page at a time.
compat = sharp / "tools/SharpProspero.Link/CompatEmitter.cs"
text = compat.read_text(encoding='utf-8')
text = text.replace('    private static CompatFunc MProtect(bool extraPage = false)\n    {\n        var a = new Asm();\n        a.Emit(0x55, 0x48, 0x89, 0xE5);                     // push rbp ; mov rbp, rsp\n        a.Emit(0x48, 0x83, 0xEC, 0x70);                     // sub rsp, 112\n        // The frame holds the three arguments at [rbp-8], [rbp-16] and [rbp-24], and the range report\n        // from [rbp-0x60] up to where the arguments start.\n        // A protection change covers whole pages: the address moves back to the start of its page and\n        // the length grows by as much, then rounds up. The platform\'s call refuses anything else, and\n        // the runtime changes protection on ranges it sized in objects rather than in pages.\n        a.Emit(0x48, 0x89, 0xF8);                           // mov rax, rdi\n        a.Emit(0x25, 0xFF, 0x3F, 0x00, 0x00);               // and eax, page - 1\n        a.Emit(0x48, 0x01, 0xC6);                           // add rsi, rax\n        a.Emit(0x48, 0x81, 0xE7, 0x00, 0xC0, 0xFF, 0xFF);   // and rdi, -page\n        a.Emit(0x48, 0x81, 0xC6, 0xFF, 0x3F, 0x00, 0x00);   // add rsi, page - 1\n        a.Emit(0x48, 0x81, 0xE6, 0x00, 0xC0, 0xFF, 0xFF);   // and rsi, -page\n        if (extraPage)\n        {\n            // The collector sizes its commit calls in objects and reads across the tail into the next\n            // page: a range whose bookkeeping is one entry sits at some byte offset in the page it starts\n            // on, and the entry itself is 168 bytes, so its last field lands past the first page. The\n            // collector does not commit the second page from a separate call -- it assumes the first\n            // commit\'s rounding covered it -- and if the first commit\'s size falls short of the second\n            // page\'s beginning, that page is never taken from the flexible pool and the first field read\n            // from it faults. One extra page beyond the rounded end fills that gap. This extension is for\n            // the standalone environment where the host process\'s address space is tighter; an application\n            // module\'s own collector sizes its commits in pages and the round-up is enough.\n            a.Emit(0x48, 0x81, 0xC6, 0x00, 0x40, 0x00, 0x00); // add rsi, page\n        }\n        a.Emit(0x48, 0x89, 0x7D, 0xF8);                     // mov [rbp-8], rdi   (addr)\n        a.Emit(0x48, 0x89, 0x75, 0xF0);                     // mov [rbp-16], rsi  (len)\n\n        a.Emit(0x83, 0xFA, PosixReadWrite);                 // cmp edx, read|write\n        a.JumpIfNotEqual("kept");\n        a.Emit(0xBA, ProtReadWrite, 0x00, 0x00, 0x00);      // mov edx, read-write\n        a.Mark("kept");\n        a.Emit(0x89, 0x55, 0xE8);                           // mov [rbp-24], edx  (prot)\n\n        // Ask what is at that address rather than guess. A range can be held without memory behind it,\n        // and the two cases need opposite calls, so the report is what decides. Its protection sits at\n        // offset 0x18 and the word saying what kind of range it is at 0x20; the whole report is 0x48\n        // bytes, which is what the call is told so it fills all of it.\n        a.Emit(0x48, 0x8B, 0x7D, 0xF8);                     // mov rdi, [rbp-8]\n        a.Emit(0x31, 0xF6);                                 // xor esi, esi   (no search)\n        a.Emit(0x48, 0x8D, 0x55, 0xA0);                     // lea rdx, [rbp-96]\n        a.Emit(0xB9, 0x48, 0x00, 0x00, 0x00);               // mov ecx, 0x48\n        a.Call("sceKernelVirtualQuery");\n        // No report came back, so nothing here knows what that range is. The one thing that must not\n        // happen then is placing memory over it: a mapping pinned to an address replaces whatever was\n        // there, and if the range did hold something - this module\'s own image, say - it is gone and\n        // the fault lands somewhere else entirely. Ask for the protection change instead and let the\n        // platform refuse it if the range is not real.\n        a.Emit(0x85, 0xC0); a.JumpIfNotEqual("keepit");\n        // Two things have to agree before fresh memory is placed over a range, because placing it is\n        // destructive: a mapping pinned to an address replaces whatever was there, so misreading a live\n        // range as empty would throw away what it held - this module\'s own data, say, whose protection\n        // the runtime changes while it starts. A range whose addresses are merely held carries no\n        // protection at all *and* is none of the kinds that have something behind them. Anything else\n        // is left to the protection change, which is harmless when the guess is wrong either way.\n        a.Emit(0x8B, 0x45, 0xB8);                           // mov eax, [rbp-72]   (protection)\n        a.Emit(0x85, 0xC0); a.JumpIfNotEqual("keepit");     // test eax, eax\n        a.Emit(0x0F, 0xB6, 0x45, 0xC0);                     // movzbl [rbp-64], eax\n        a.Emit(0xA8, RangeIsBacked);                        // test al, backed\n        a.JumpIfNotEqual("keepit");\n\n        // Nothing behind that range yet, so put memory behind it, pinned to the addresses that are\n        // already held. This is the step the protection call cannot do: that one reports success over a\n        // range that holds nothing and leaves it as empty as it found it, so the runtime believes it\n        // owns memory it has not been given and faults on the first write.\n        a.Emit(0x48, 0x8D, 0x7D, 0xF8);                     // lea rdi, [rbp-8]\n        a.Emit(0x48, 0x8B, 0x75, 0xF0);                     // mov rsi, [rbp-16]\n        a.Emit(0x8B, 0x55, 0xE8);                           // mov edx, [rbp-24]\n        a.Emit(0xB9, MapFixed, 0x00, 0x00, 0x00);           // mov ecx, pinned\n        a.Emit(0x45, 0x31, 0xC0);                           // xor r8d, r8d  (read past the arguments)\n        a.Call("sceKernelMapFlexibleMemory");\n        a.Emit(0x85, 0xC0); a.JumpIfEqual("done");          // test eax, eax\n        a.JumpIfAlways("refuse");\n\n        // Memory is already there, so this is a protection change on what it holds and nothing moves.\n        a.Mark("keepit");\n        a.Emit(0x48, 0x8B, 0x7D, 0xF8);                     // mov rdi, [rbp-8]\n        a.Emit(0x48, 0x8B, 0x75, 0xF0);                     // mov rsi, [rbp-16]\n        a.Emit(0x8B, 0x55, 0xE8);                           // mov edx, [rbp-24]\n        a.Call("sceKernelMprotect");\n        a.Emit(0x85, 0xC0); a.JumpIfNotEqual("refuse");     // test eax, eax\n        a.Mark("done");\n        a.Emit(0x31, 0xC0, 0xC9, 0xC3);                     // xor eax, eax ; leave ; ret\n        // Whichever of the two calls refused, it answered a code carrying the reason, and neither\n        // leaves that reason where the runtime reads it.\n        a.Mark("refuse");\n        EmitCodedErrno(a);\n        a.Emit(0xB8, 0xFF, 0xFF, 0xFF, 0xFF, 0xC9, 0xC3);   // mov eax, -1 ; leave ; ret\n\n        (byte[] code, (int, string)[] relocs) = a.Build();\n        return new("mprotect", false, code, relocs);\n    }\n\n', '    private static CompatFunc MProtect(bool extraPage = false)\n    {\n        var a = new Asm();\n        a.Emit(0x55, 0x48, 0x89, 0xE5);                     // push rbp ; mov rbp, rsp\n        a.Emit(0x48, 0x83, 0xEC, 0x70);                     // sub rsp, 112\n        // The frame holds the three arguments at [rbp-8], [rbp-16] and [rbp-24], and the range report\n        // from [rbp-0x60] up to where the arguments start.\n        // A protection change covers whole pages: the address moves back to the start of its page and\n        // the length grows by as much, then rounds up. The platform\'s call refuses anything else, and\n        // the runtime changes protection on ranges it sized in objects rather than in pages.\n        a.Emit(0x48, 0x89, 0xF8);                           // mov rax, rdi\n        a.Emit(0x25, 0xFF, 0x3F, 0x00, 0x00);               // and eax, page - 1\n        a.Emit(0x48, 0x01, 0xC6);                           // add rsi, rax\n        a.Emit(0x48, 0x81, 0xE7, 0x00, 0xC0, 0xFF, 0xFF);   // and rdi, -page\n        a.Emit(0x48, 0x81, 0xC6, 0xFF, 0x3F, 0x00, 0x00);   // add rsi, page - 1\n        a.Emit(0x48, 0x81, 0xE6, 0x00, 0xC0, 0xFF, 0xFF);   // and rsi, -page\n        if (extraPage)\n        {\n            // The collector sizes its commit calls in objects and reads across the tail into the next\n            // page: a range whose bookkeeping is one entry sits at some byte offset in the page it starts\n            // on, and the entry itself is 168 bytes, so its last field lands past the first page. The\n            // collector does not commit the second page from a separate call -- it assumes the first\n            // commit\'s rounding covered it -- and if the first commit\'s size falls short of the second\n            // page\'s beginning, that page is never taken from the flexible pool and the first field read\n            // from it faults. One extra page beyond the rounded end fills that gap. This extension is for\n            // the standalone environment where the host process\'s address space is tighter; an application\n            // module\'s own collector sizes its commits in pages and the round-up is enough.\n            a.Emit(0x48, 0x81, 0xC6, 0x00, 0x40, 0x00, 0x00); // add rsi, page\n        }\n        a.Emit(0x48, 0x89, 0x7D, 0xF8);                     // mov [rbp-8], rdi   (addr)\n        a.Emit(0x48, 0x89, 0x75, 0xF0);                     // mov [rbp-16], rsi  (len)\n\n        a.Emit(0x83, 0xFA, PosixReadWrite);                 // cmp edx, read|write\n        a.JumpIfNotEqual("kept");\n        a.Emit(0xBA, ProtReadWrite, 0x00, 0x00, 0x00);      // mov edx, read-write\n        a.Mark("kept");\n        a.Emit(0x89, 0x55, 0xE8);                           // mov [rbp-24], edx  (prot)\n\n        // Commit each 16 KiB page independently: a range can mix backed and reserved pages.\n        a.Mark("queryPage");\n        // Ask what is at that address rather than guess. A range can be held without memory behind it,\n        // and the two cases need opposite calls, so the report is what decides. Its protection sits at\n        // offset 0x18 and the word saying what kind of range it is at 0x20; the whole report is 0x48\n        // bytes, which is what the call is told so it fills all of it.\n        a.Emit(0x48, 0x8B, 0x7D, 0xF8);                     // mov rdi, [rbp-8]\n        a.Emit(0x31, 0xF6);                                 // xor esi, esi   (no search)\n        a.Emit(0x48, 0x8D, 0x55, 0xA0);                     // lea rdx, [rbp-96]\n        a.Emit(0xB9, 0x48, 0x00, 0x00, 0x00);               // mov ecx, 0x48\n        a.Call("sceKernelVirtualQuery");\n        // No report came back, so nothing here knows what that range is. The one thing that must not\n        // happen then is placing memory over it: a mapping pinned to an address replaces whatever was\n        // there, and if the range did hold something - this module\'s own image, say - it is gone and\n        // the fault lands somewhere else entirely. Ask for the protection change instead and let the\n        // platform refuse it if the range is not real.\n        a.Emit(0x85, 0xC0); a.JumpIfNotEqual("keepit");\n        // Two things have to agree before fresh memory is placed over a range, because placing it is\n        // destructive: a mapping pinned to an address replaces whatever was there, so misreading a live\n        // range as empty would throw away what it held - this module\'s own data, say, whose protection\n        // the runtime changes while it starts. A range whose addresses are merely held carries no\n        // protection at all *and* is none of the kinds that have something behind them. Anything else\n        // is left to the protection change, which is harmless when the guess is wrong either way.\n        a.Emit(0x8B, 0x45, 0xB8);                           // mov eax, [rbp-72]   (protection)\n        a.Emit(0x85, 0xC0); a.JumpIfNotEqual("keepit");     // test eax, eax\n        a.Emit(0x0F, 0xB6, 0x45, 0xC0);                     // movzbl [rbp-64], eax\n        a.Emit(0xA8, RangeIsBacked);                        // test al, backed\n        a.JumpIfNotEqual("keepit");\n\n        // Nothing behind that range yet, so put memory behind it, pinned to the addresses that are\n        // already held. This is the step the protection call cannot do: that one reports success over a\n        // range that holds nothing and leaves it as empty as it found it, so the runtime believes it\n        // owns memory it has not been given and faults on the first write.\n        a.Emit(0x48, 0x8D, 0x7D, 0xF8);                     // lea rdi, [rbp-8]\n        a.Emit(0xBE, 0x00, 0x40, 0x00, 0x00);               // mov esi, 16 KiB\n        a.Emit(0x8B, 0x55, 0xE8);                           // mov edx, [rbp-24]\n        a.Emit(0xB9, MapFixed, 0x00, 0x00, 0x00);           // mov ecx, pinned\n        a.Emit(0x45, 0x31, 0xC0);                           // xor r8d, r8d  (read past the arguments)\n        a.Call("sceKernelMapFlexibleMemory");\n        a.Emit(0x85, 0xC0); a.JumpIfEqual("done");          // test eax, eax\n        a.JumpIfAlways("refuse");\n\n        // Memory is already there, so this is a protection change on what it holds and nothing moves.\n        a.Mark("keepit");\n        a.Emit(0x48, 0x8B, 0x7D, 0xF8);                     // mov rdi, [rbp-8]\n        a.Emit(0xBE, 0x00, 0x40, 0x00, 0x00);               // mov esi, 16 KiB\n        a.Emit(0x8B, 0x55, 0xE8);                           // mov edx, [rbp-24]\n        a.Call("sceKernelMprotect");\n        a.Emit(0x85, 0xC0); a.JumpIfNotEqual("refuse");     // test eax, eax\n        a.Mark("done");\n        a.Emit(0x48, 0x81, 0x45, 0xF8, 0x00, 0x40, 0x00, 0x00); // addr += page\n        a.Emit(0x48, 0x81, 0x6D, 0xF0, 0x00, 0x40, 0x00, 0x00); // remaining -= page\n        a.JumpIfNotEqual("queryPage");\n        a.Emit(0x31, 0xC0, 0xC9, 0xC3);                     // xor eax, eax ; leave ; ret\n        // Whichever of the two calls refused, it answered a code carrying the reason, and neither\n        // leaves that reason where the runtime reads it.\n        a.Mark("refuse");\n        EmitCodedErrno(a);\n        a.Emit(0xB8, 0xFF, 0xFF, 0xFF, 0xFF, 0xC9, 0xC3);   // mov eax, -1 ; leave ; ret\n\n        (byte[] code, (int, string)[] relocs) = a.Build();\n        return new("mprotect", false, code, relocs);\n    }\n\n')
compat.write_text(text, encoding='utf-8')

# Preserve live bytes neighboring sub-page releases.
compat = sharp / "tools/SharpProspero.Link/CompatEmitter.cs"
text = compat.read_text(encoding='utf-8')
text = text.replace("    // none of these and carries no protection at all is one whose addresses are held and nothing more.\n    private const byte RangeIsBacked = 0x0F;\n\n    private static CompatFunc Mmap()\n    {\n        var a = new Asm();\n        a.Emit(0x55, 0x48, 0x89, 0xE5);                     // push rbp ; mov rbp, rsp\n        a.Emit(0x48, 0x83, 0xEC, 0x10);                     // sub rsp, 16   (the address slot)\n        // A length is rounded up to a whole page. Asking for memory hands back whole pages anyway, and\n        // both of the platform's calls refuse a length that is not a multiple of one - so a request for\n        // a few hundred bytes, which the ordinary call answers with a page, would be refused outright.\n", '    // none of these and carries no protection at all is one whose addresses are held and nothing more.\n    private const byte RangeIsBacked = 0x0F;\n\n    // Releasing part of a PS5 page must retain the neighboring live bytes.\n    private static void InwardPages(Asm a, string empty)\n    {\n        a.Emit(0x48, 0x89, 0xF8, 0x48, 0x01, 0xF0); // end = addr + len\n        a.Emit(0x48, 0x25, 0x00, 0xC0, 0xFF, 0xFF); // end &= -16384\n        a.Emit(0x48, 0x81, 0xC7, 0xFF, 0x3F, 0x00, 0x00);\n        a.Emit(0x48, 0x81, 0xE7, 0x00, 0xC0, 0xFF, 0xFF); // addr = ceil(addr/page)\n        a.Emit(0x48, 0x29, 0xF8); // len = end - addr\n        a.JumpIfEqual(empty);\n        a.JumpIfNotNegative("releaseRange");\n        a.JumpIfAlways(empty);\n        a.Mark("releaseRange");\n        a.Emit(0x48, 0x89, 0xC6); // rsi = len\n    }\n\n    private static CompatFunc Mmap()\n    {\n        var a = new Asm();\n        a.Emit(0x55, 0x48, 0x89, 0xE5);                     // push rbp ; mov rbp, rsp\n        a.Emit(0x48, 0x83, 0xEC, 0x20);                     // sub rsp, 16   (the address slot)\n        a.Emit(0x48, 0x89, 0x7D, 0xF0); // original addr\n        a.Emit(0x89, 0x4D, 0xE8); // original flags\n        a.Emit(0x85, 0xD2); a.JumpIfNotEqual("fullRange");\n        a.Emit(0xF6, 0xC1, MapFixed); a.JumpIfEqual("fullRange");\n        InwardPages(a, "emptyRelease");\n        a.Mark("fullRange");\n        // A length is rounded up to a whole page. Asking for memory hands back whole pages anyway, and\n        // both of the platform\'s calls refuse a length that is not a multiple of one - so a request for\n        // a few hundred bytes, which the ordinary call answers with a page, would be refused outright.\n')
